import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { Agent, Space } from '../types'

const PANE = 'agent-groups'
const TITLE = 'Agents'
const EVERY_MS = 15_000
// How long a mesh name found for a pane is kept before the script looks it up again.
const MESH_MS = 60_000

const spaces = atom({ plugin: 'agent-groups', key: 'spaces' } as const, [])
const agents = atom({ plugin: 'agent-groups', key: 'agents' } as const, [])
const folded = atom({ plugin: 'agent-groups', key: 'folded' } as const, [])
const checkedAt = atom({ plugin: 'agent-groups', key: 'checkedAt' } as const, 0)

// Theme keys, not raw ANSI names: they follow the person's Claude Code theme, light or dark.
// Idle is green and working is Claude's orange, as herdr's sidebar and Claude Code draw them.
const LOOK = {
  text: 'text',
  quiet: 'subtle',
  faint: 'inactive',
  idle: 'success',
  working: 'claude',
  waiting: 'warning',
} as const

// Asks herdr for its workspaces and agents, and joins each agent to its Claude session's mesh
// name through the pane's process. Reads only the `name` field of each session file.
// The last argument holds the mesh names already known, by pane: those panes are not asked again.
const HERDR = [
  'python3',
  '-c',
  `
import json, os, subprocess, sys
known = json.loads(sys.argv[1])
def h(*a):
    r = subprocess.run(['herdr', *a], capture_output=True, text=True, timeout=10)
    return json.loads(r.stdout)['result']
def mesh_of(pane):
    mesh = None
    try:
        for p in h('pane', 'process-info', '--pane', pane)['process_info'].get('foreground_processes', []):
            f = os.path.expanduser('~/.claude/sessions/%d.json' % p['pid'])
            if os.path.exists(f):
                with open(f) as s:
                    mesh = json.load(s).get('name')
    except Exception:
        pass
    return mesh
ws = h('workspace', 'list')['workspaces']
out = []
for a in h('agent', 'list')['agents']:
    pane = a['pane_id']
    out.append({'space': a['workspace_id'], 'pane': pane, 'topic': a.get('terminal_title_stripped') or '',
                'status': a.get('agent_status') or '', 'mesh': known.get(pane) or mesh_of(pane)})
print(json.dumps({'spaces': [{'id': w['workspace_id'], 'label': w['label'], 'status': w.get('agent_status') or '',
                              'isFocused': bool(w.get('focused'))} for w in ws], 'agents': out}))
`,
]

// Mesh names found so far, by pane, and when the list was started. Only found names are kept,
// so a pane whose session has not started yet is asked again on the next refresh.
const meshes = new Map<string, string>()
let meshesAt = 0

export function parseHerdr(stdout: string): { spaces: Space[]; agents: Agent[] } | undefined {
  try {
    const data = JSON.parse(stdout) as { spaces?: Space[]; agents?: (Agent & { mesh?: string | null })[] }
    if (!Array.isArray(data.spaces) || !Array.isArray(data.agents)) return undefined
    return {
      spaces: data.spaces,
      agents: data.agents.map(({ mesh, ...a }) => (mesh ? { ...a, mesh } : a)),
    }
  } catch {
    return undefined
  }
}

// Without herdr: ListAgents' peer sessions, grouped by the folder their mesh name starts with.
// "  mandr-c3 [7e0719]  ·  interactive  ·  idle  ·  started 21h ago"
const LINE = /^\s+(\S+)(?:\s+\[[^\]]+\])?\s+·\s+\S+\s+·\s+(\S+)(?:\s+·\s+started\s+(.+?))?\s*$/

export const groupOf = (name: string) => (name.includes('-') ? name.slice(0, name.lastIndexOf('-')) : name)

export function fromPeers(text: string): { spaces: Space[]; agents: Agent[] } {
  const list = text.split('\n').flatMap(row => {
    const m = LINE.exec(row)
    return m ? [{ name: m[1] ?? '', status: m[2] ?? '' }] : []
  })
  const ids = [...new Set(list.map(p => groupOf(p.name)))].sort()
  return {
    spaces: ids.map(id => ({ id, label: id, status: '', isFocused: false })),
    agents: list.map(p => ({ space: groupOf(p.name), pane: p.name, topic: p.name, status: p.status })),
  }
}

// The status names herdr and the agent list use, by how the pane shows them. Others show as idle.
const STATUS = {
  working: new Set(['working', 'busy', 'running']),
  waiting: new Set(['waiting', 'blocked', 'needs_input', 'input']),
}

export const isWorking = (status: string) => STATUS.working.has(status)
export const isWaiting = (status: string) => STATUS.waiting.has(status)

export const toggled = (list: string[], id: string) => (list.includes(id) ? list.filter(n => n !== id) : [...list, id])

// A space's status: working if any agent works, waiting if any waits, else idle.
export function spaceStatus(members: Agent[], own: string): string {
  if (members.some(a => isWorking(a.status))) return 'working'
  if (members.some(a => isWaiting(a.status))) return 'waiting'
  return members.length > 0 ? 'idle' : own || 'empty'
}

export const fit = (text: string, room: number) => (text.length <= Math.max(room, 4) ? text : `${text.slice(0, Math.max(room, 4) - 1)}…`)

// A session row's columns: status glyph, name, topic. The name column is a third of the row,
// 8 to 24 wide, so names and topics line up under each other in every group.
// A group header's label room: the fold glyph, " · here" and a count with its status fit beside it.
export const labelRoom = (width: number) => width - 24

export function columnsOf(width: number): { name: number; topic: number } {
  const room = width - 4
  const name = Math.min(24, Math.max(8, Math.floor(room / 3)))
  return { name, topic: Math.max(4, room - name - 1) }
}

export function ago(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  return s < 60 ? 'just now' : s < 3600 ? `${Math.floor(s / 60)}m ago` : `${Math.floor(s / 3600)}h ago`
}

const glyph = (status: string) => (isWorking(status) ? '◑' : isWaiting(status) ? '◷' : '○')
const tint = (status: string) => (isWorking(status) ? LOOK.working : isWaiting(status) ? LOOK.waiting : LOOK.idle)

// `isFresh` looks up every mesh name again: on open and on the refresh button.
async function refresh($: EngineInterface, isFresh = false) {
  const start = await $.clock.now()
  if (isFresh || start - meshesAt >= MESH_MS) {
    meshes.clear()
    meshesAt = start
  }
  let got: { spaces: Space[]; agents: Agent[] } | undefined
  try {
    const { exitCode, stdout } = await $.process.run([...HERDR, JSON.stringify(Object.fromEntries(meshes))], { timeoutMs: 30_000 })
    if (exitCode === 0) got = parseHerdr(stdout)
    for (const a of got?.agents ?? []) if (a.mesh !== undefined) meshes.set(a.pane, a.mesh)
  } catch {
    // Not inside herdr: fall back to the mesh names below.
  }
  if (got === undefined) {
    try {
      const { text } = await $.tool.call({ tool: 'ListAgents' })
      if (text !== undefined) got = fromPeers(text)
    } catch {
      // Keep the last list; the header says how old it is.
    }
  }
  if (got !== undefined) {
    const { spaces: s, agents: a } = got
    await update($, spaces, () => s)
    await update($, agents, () => a)
  }
  const now = await $.clock.now()
  await update($, checkedAt, () => now)
}

export const register: Register = on => {
  // One refresh timer, and only while the pane is open.
  let ticker: Timer | undefined

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'agent-groups', description: 'Open a pane of your agents, by their herdr names, in groups you can fold' })
    return next(e)
  })

  on('command.run', { command: 'agent-groups' }, async $ => {
    await refresh($, true)
    await $.ui.open({ id: PANE, title: TITLE })
    ticker ??= $.clock.every(EVERY_MS, () => void refresh($))
    const n = (await read($, agents)).length
    return { text: `Agents pane opened: ${n} agent${n === 1 ? '' : 's'}.` }
  })

  const stop = () => {
    ticker?.cancel()
    ticker = undefined
  }

  // The person's close mark or key. The pane's own close button stops the timer itself,
  // because a plugin's own `$.ui.close` does not reach its own hooks.
  on('ui.close', { id: PANE }, async ($, e, next) => {
    stop()
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const [list, all, shut, at, now] = await Promise.all([read($, spaces), read($, agents), read($, folded), read($, checkedAt), $.clock.now()])
    // The pane's own body width: docked beside the transcript it is far narrower than the terminal.
    const columns = e.props.bodyColumns ?? e.viewport?.columns ?? 60

    const fold = (id: string) => () => update($, folded, f => toggled(f, id))
    const allShut = list.length > 0 && list.every(s => shut.includes(s.id))
    const right = `${list.length} group${list.length === 1 ? '' : 's'} · ${ago(now - at)}`
    const cols = columnsOf(columns)

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" justifyContent="space-between">
          <Text color={LOOK.text} bold>{TITLE}</Text>
          <Text color={LOOK.faint}>{right}</Text>
        </Box>
        {list.length === 0 && <Text color={LOOK.faint}>No agents found.</Text>}
        {list.map((s, i) => {
          const members = all.filter(a => a.space === s.id)
          const status = spaceStatus(members, s.status)
          const isShut = shut.includes(s.id)
          return (
            <Box key={`s-${s.id}`} flexDirection="column">
              <Box flexDirection="row" justifyContent="space-between">
                <Button key={`fold-${s.id}`} plain hotkey={i < 9 ? String(i + 1) : undefined} onPress={fold(s.id)}>
                  <Text color={LOOK.quiet}>{isShut ? '▸ ' : '▾ '}</Text>
                  <Text color={LOOK.text} bold>{fit(s.label, labelRoom(columns))}</Text>
                  {s.isFocused && <Text color={LOOK.working}> · here</Text>}
                </Button>
                <Box key={`count-${s.id}`}>
                  <Text>
                    <Text color={LOOK.faint}>{`${members.length} `}</Text>
                    <Text color={tint(status)}>{`${glyph(status)} ${status}`}</Text>
                  </Text>
                </Box>
              </Box>
              {!isShut &&
                members.map(a => (
                  <Box key={`a-${a.pane}`}>
                    <Text>
                      <Text color={tint(a.status)}>{`  ${glyph(a.status)} `}</Text>
                      <Text color={LOOK.faint}>{fit(a.mesh ?? a.pane, cols.name).padEnd(cols.name)}</Text>
                      <Text color={LOOK.quiet}>{` ${fit(a.topic || 'no topic yet', cols.topic)}`}</Text>
                    </Text>
                  </Box>
                ))}
            </Box>
          )
        })}
        <Box flexDirection="row" flexWrap="wrap" columnGap={2} marginTop={1}>
          <Button key="ag-all" plain hotkey="a" label={allShut ? 'unfold all' : 'fold all'} onPress={() => update($, folded, () => (allShut ? [] : list.map(s => s.id)))} />
          <Button key="ag-refresh" plain hotkey="r" label="refresh" onPress={() => refresh($, true)} />
          <Button key="ag-close" plain hotkey="q" label="close" onPress={() => $.ui.close({ id: PANE }).then(stop)} />
        </Box>
      </Box>
    )
  })
}

