// One herdr workspace: a sidebar entry, by the name the person gave it.
export type Space = { id: string; label: string; status: string; isFocused: boolean }

// One Claude agent in a workspace: what it is working on, and its mesh name when known.
export type Agent = { space: string; pane: string; topic: string; status: string; mesh?: string }

declare module 'claude-code' {
  interface PluginState {
    'agent-groups': {
      spaces: Space[]
      agents: Agent[]
      // The spaces the person folded, by id.
      folded: string[]
      checkedAt: number
    }
  }
}
